const originalBanks=new Map(sets.map(s=>[s.theme,s.qs.slice()]));
const replaceBank=(theme,qs)=>{sets.find(s=>s.theme===theme).qs=qs};
const pairs=(theme,rows)=>{
 const qs=[],seen=new Set();
 rows.trim().split('\n').forEach((line,i,arr)=>{
  const parts=line.split('|');const [left,right]=parts.map(g=>g.slice(g.indexOf(':')+1).split(' '));const [lr,rr]=parts.map(g=>g.slice(0,g.indexOf(':')));const readings=new Map([...left.map(w=>[w,lr]),...right.map(w=>[w,rr])]);
  const difficulty=Math.min(10,1+Math.floor(i*10/arr.length));
  const insert=(a,b,key)=>{const id=[a,b].sort().join('／');if(a===b||seen.has(id))return;seen.add(id);qs.push({q:'読み方は同じ？',a,b,key,format:'same',difficulty,readA:readings.get(a),readB:readings.get(b),note:a+'（'+readings.get(a)+'）／'+b+'（'+readings.get(b)+'）'})};
  for(const group of [left,right])for(let a=0;a<group.length;a++)for(let b=a+1;b<group.length;b++)insert(group[a],group[b],0);
  for(const a of left)for(const b of right)insert(a,b,1);
 });replaceBank(theme,qs)
};
