const sameBasics=(rows)=>{const result=[];const seen=new Set();for(const [i,line] of rows.split('\n').entries()){const groups=line.split('|').map(x=>{const [r,words]=x.split(':');return {r,words:words.split(' ')}});const addPair=(a,b,ra,rb)=>{const id=[a,b].sort().join('／');if(a===b||seen.has(id))return;seen.add(id);result.push({q:'読み方は同じ？',a,b,key:ra===rb?0:1,format:'same',difficulty:1+Math.floor(i*6/rows.split('\n').length),readA:ra,readB:rb,note:a+'（'+ra+'）／'+b+'（'+rb+'）'})};for(const g of groups)for(let x=0;x<g.words.length;x++)for(let y=x+1;y<g.words.length;y++)addPair(g.words[x],g.words[y],g.r,g.r);for(const a of groups[0].words)for(const b of groups[1].words)addPair(a,b,groups[0].r,groups[1].r)}return result};
const relevel=(theme,easy)=>{const set=sets.find(s=>s.theme===theme);const advanced=set.qs;advanced.forEach(q=>q.difficulty=7+Math.floor((q.difficulty-1)*4/10));const keys=new Set(easy.map(q=>[q.a,q.b].sort().join('|')));set.qs=[...easy,...advanced.filter(q=>!keys.has([q.a,q.b].sort().join('|')))]};
