const knownReadings=new Map();for(const g of readingGroups){if(!knownReadings.has(g.reading))knownReadings.set(g.reading,{rank:g.rank,reading:g.reading,words:new Set()});const x=knownReadings.get(g.reading);x.rank=Math.max(x.rank,g.rank);for(const w of g.words)x.words.add(w)}
const readGroups=[...knownReadings.values()].map(g=>({...g,words:[...g.words]}));
const readingPair=(a,ra,b,rb,difficulty)=>({q:'読み方は同じ？',a,b,readA:ra,readB:rb,key:ra===rb?0:1,format:'same',difficulty,lang:'ja',note:a+'（'+ra+'）／'+b+'（'+rb+'）',family:'読み:'+ra+'|'+rb});
function editDistance(a,b){const x=Array.from(a),y=Array.from(b);let row=Array.from({length:y.length+1},(_,i)=>i);for(let i=0;i<x.length;i++){let next=[i+1];for(let j=0;j<y.length;j++)next.push(Math.min(row[j+1]+1,next[j]+1,row[j]+Number(x[i]!==y[j])));row=next}return row[y.length]}
const generatedReading=[];for(const g of readGroups){for(let i=0;i<g.words.length;i++)for(let j=i+1;j<g.words.length;j++)generatedReading.push(readingPair(g.words[i],g.reading,g.words[j],g.reading,g.rank))}
for(let i=0;i<readGroups.length;i++){const a=readGroups[i];const near=readGroups.slice(i+1).filter(b=>Math.abs(a.rank-b.rank)<=2&&editDistance(a.reading,b.reading)===1).sort((b,c)=>Math.abs(a.rank-b.rank)-Math.abs(a.rank-c.rank));for(const b of near.slice(0,3)){for(let k=0;k<Math.min(3,Math.max(a.words.length,b.words.length));k++)generatedReading.push(readingPair(a.words[k%a.words.length],a.reading,b.words[(k+1)%b.words.length],b.reading,Math.max(a.rank,b.rank)))}}
