for(const [ti,theme] of jpThemes.entries()){const set=sets.find(s=>s.theme===theme);set.qs=set.qs.filter(q=>!/[（(]/.test(q.a+q.b)&&q.difficulty<=5);const seen=new Set(set.qs.map(q=>[q.a,q.b].sort().join('|')));for(const q of [...specialReads,...generatedReading.filter((_,i)=>i%2===ti)]){if(q.a===q.b)continue;const key=[q.a,q.b].sort().join('|');if(!seen.has(key)){set.qs.push(q);seen.add(key)}}}


