const sem=sets.find(s=>s.theme==='意味が近い？ 反対？');sem.qs=sem.qs.filter(q=>/^[一-龯々]{2,4}$/.test(q.a)&&/^[一-龯々]{2,4}$/.test(q.b));
const semSeen=new Set(sem.qs.map(q=>[q.a,q.b].sort().join('|')));
const semAdd=(a,b,key,d,da,db)=>{if(a===b||!(/^[一-龯々]{2,4}$/.test(a)&&/^[一-龯々]{2,4}$/.test(b)))return;const k=[a,b].sort().join('|');if(semSeen.has(k))return;semSeen.add(k);sem.qs.push({q:'2つの言葉の意味の関係は？',a,b,key,format:'meaning',difficulty:d,note:a+'：'+da+' ／ '+b+'：'+db,family:'意味:'+da+'|'+db})};
for(const g of semanticGroups){for(const [ws,def] of [[g.a,g.da],[g.b,g.db]])for(let i=0;i<ws.length;i++)for(let j=i+1;j<ws.length;j++)semAdd(ws[i],ws[j],0,g.d,def,def);for(const a of g.a)for(const b of g.b)semAdd(a,b,1,g.d,g.da,g.db)}
const kb=sets.find(s=>s.theme==='漢字の読み方'),kSeen=new Set(kb.qs.map(q=>q.q+'|'+[q.a,q.b].sort().join('|')));
function kanjiAdd(word,read,wrong,d){if(read===wrong||/[（(]/.test(word))return;const q=word+' の読み方は？',key=q+'|'+[read,wrong].sort().join('|');if(kSeen.has(key))return;kSeen.add(key);kb.qs.push({q,a:read,b:wrong,key:0,format:'ab',difficulty:d,note:word+'（'+read+'）',family:'漢字:'+word})}
