function addExpanded(theme,items){let set=sets.find(s=>s.theme===theme);if(!set){set={theme,qs:[]};sets.push(set)}const keys=new Set(set.qs.map(q=>q.q+'|'+[q.a,q.b].sort().join('|')));for(const q of items){const k=q.q+'|'+[q.a,q.b].sort().join('|');if(q.a===q.b&&q.format!=='tf'||keys.has(k))continue;keys.add(k);set.qs.push(q)}}
const abQ=(q,a,b,d,note,family)=>({q,a:String(a),b:String(b),key:0,format:'ab',difficulty:d,note,family});
const tfQ=(q,key,d,note,family)=>({q,a:'',b:'',key,format:'tf',difficulty:d,note,family});
const diff=(i,n)=>Math.min(10,1+Math.floor(10*i/n));
const world=[],worldTF=[],japanMore=[];
for(let i=0;i<countryRows.length;i++){const [c,cap,region,currency]=countryRows[i];const regional=countryRows.filter(r=>r[2]===region&&r[0]!==c);const wrong=regional[(i*7)%regional.length];const d=diff(i,countryRows.length),fam='国:'+c;world.push(abQ(c+'の首都は？',cap,wrong[1],d,c+'の首都は'+cap+'。',fam));world.push(abQ(cap+'が首都なのは？',c,wrong[0],d,cap+'は'+c+'の首都。',fam));const other=countryRows.find((r,j)=>r[2]!==region&&j>i%30)||countryRows[0];worldTF.push(tfQ(c+'の首都は'+(i%2?wrong[1]:cap)+'である',i%2?1:0,d,c+'の首都は'+cap+'。',fam));worldTF.push(tfQ(c+'は'+(i%2?region:other[2])+'に位置する',i%2?0:1,d,c+'は'+region+'に位置する。',fam));}
