const elScience=[],elTF=[],elSize=[];
for(let i=0;i<elementRows.length;i++){const e=elementRows[i],w=elementRows[(i+((i%7)+1))%elementRows.length],d=diff(i,elementRows.length),fam='元素:'+e.symbol;
elScience.push(abQ(e.name+'の元素記号は？',e.symbol,w.symbol,d,e.name+'：'+e.symbol+'（原子番号'+e.z+'）。',fam));elScience.push(abQ('元素記号 '+e.symbol+' は？',e.name,w.name,d,e.symbol+'は'+e.name+'。',fam));
elTF.push(tfQ(e.name+'の原子番号は'+(i%2?e.z:w.z)+'である',i%2?0:1,d,e.name+'の原子番号は'+e.z+'。',fam));
const z1=e.z>w.z?e:w,z2=e.z>w.z?w:e;elSize.push(abQ('原子番号が大きい元素は？',z1.name,z2.name,Math.max(4,d),z1.name+' '+z1.z+'／'+z2.name+' '+z2.z,'元素番号:'+e.symbol+'|'+w.symbol))}
addExpanded('身近な科学',elScience);addExpanded('○× 科学・暮らし',elTF);addExpanded('どっちが大きい？',elSize);
const pg=[],pgTF=[];for(let i=0;i<prefRows.length;i++){const [name,cap,region,sea]=prefRows[i];const fam='都道府県:'+name;const other=prefRows.find((r,j)=>j!==i&&r[1]!==cap&&r[2]===region)||prefRows[(i+7)%47];const d=3+i%6;if(name!=='東京'){pg.push(abQ(name+'の県庁所在地（道・府庁所在地を含む）は？',cap,other[1],d,name+'の行政庁所在地は'+cap+'。',fam));pg.push(abQ(cap+'が県庁所在地なのは？',name,other[0],d,cap+'は'+name+'の行政庁所在地。',fam))}
pgTF.push(tfQ(name+'は海に面している',sea==='内陸'?1:0,d,sea==='内陸'?name+'は内陸県。':name+'は海に面する。',fam))}
